function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }

const j = $json.body || $json;
const action = String(j.action || '').trim();
const id = pgNum(j.id);
const reviewer = String(j.reviewer || '').trim() || 'unbekannt';

let sql;

if (action === 'reject') {
  sql = `UPDATE trading.learning_rule_proposals
    SET status = 'rejected', reviewed_at = now(), reviewed_by = ${pgStr(reviewer)}
    WHERE id = ${id} AND status = 'proposed';`;
} else if (action === 'approve') {
  const eligible = `EXISTS (SELECT 1 FROM trading.learning_rule_proposals WHERE id = ${id} AND status = 'proposed')`;
  const proposalType = String(j.proposal_type || 'weight_adjustment').trim();
  const targetType = String(j.target_type || '').trim();
  const targetValue = String(j.target_value || '').trim();
  const proposedValueRaw = j.proposed_value;

  // Welle 3, AP9: der Handelslernagent (09b) erzeugt vier weitere Vorschlagstypen
  // neben dem bestehenden weight_adjustment. Jeder Typ hat einen eigenen, echten
  // Aktivierungspfad (kein reines Statusfeld ohne Wirkung) - siehe
  // docs/LERNAGENT_HANDELSSTRATEGIEN.md fuer die vollstaendige Zuordnung.
  if (proposalType === 'threshold_adjustment') {
    // target_type = config_key aus trading.pipeline_config (z.B. MIN_REWARD_RISK_RATIO,
    // MAX_RISK_PER_TRADE_PCT, MAX_POSITION_VALUE_PCT) - deckt AP9s "Schwellenwertanpassung",
    // "Verringerung der Positionsgroesse" und "Aenderung der CRV-Mindestanforderung" ab.
    const proposedValue = pgNum(proposedValueRaw);
    sql = `BEGIN;
      UPDATE trading.pipeline_config SET value_numeric = ${proposedValue}, updated_at = now()
        WHERE config_key = ${pgStr(targetType)} AND ${eligible};
      UPDATE trading.learning_rule_proposals
        SET status = 'activated', reviewed_at = now(), reviewed_by = ${pgStr(reviewer)}, activated_at = now()
        WHERE id = ${id} AND status = 'proposed';
      COMMIT;`;
  } else if (proposalType === 'strategy_parameter_change') {
    // target_type = Strategie (z.B. trend_following), target_value = parameter_key
    // (z.B. horizon_days) - deckt AP9s "Aenderung des Zeitstops" ab. HINWEIS: die
    // Aktivierung schreibt korrekt nach trading.strategy_parameters, "02" liest diese
    // Tabelle aber noch nicht (siehe docs/LERNAGENT_HANDELSSTRATEGIEN.md, bewusste
    // Einschraenkung) - der Vorschlag ist freigebbar, aber ohne Wirkung bis "02" folgt.
    const proposedValue = pgNum(proposedValueRaw);
    sql = `BEGIN;
      UPDATE trading.strategy_parameters SET parameter_value = ${proposedValue}, version = version + 1, source_proposal_id = ${id}, updated_at = now()
        WHERE strategy = ${pgStr(targetType)} AND parameter_key = ${pgStr(targetValue)} AND ${eligible};
      UPDATE trading.learning_rule_proposals
        SET status = 'activated', reviewed_at = now(), reviewed_by = ${pgStr(reviewer)}, activated_at = now()
        WHERE id = ${id} AND status = 'proposed';
      COMMIT;`;
  } else if (proposalType === 'regime_restriction') {
    // target_type = Strategie, target_value = combined_regime, proposed_value = neuer
    // fit_multiplier (0 = de facto blockiert). Deckt AP9s "Regimebeschraenkung" ab.
    const proposedValue = pgNum(proposedValueRaw);
    sql = `BEGIN;
      UPDATE trading.strategy_regime_matrix
        SET fit_multiplier = ${proposedValue}, blocked = (${proposedValue} <= 0), notes = COALESCE(notes, '') || ' [Welle 3 Lernvorschlag #${id} aktiviert]'
        WHERE rule_version = 'regime-matrix-v1' AND strategy = ${pgStr(targetType)} AND combined_regime = ${pgStr(targetValue)} AND ${eligible};
      UPDATE trading.learning_rule_proposals
        SET status = 'activated', reviewed_at = now(), reviewed_by = ${pgStr(reviewer)}, activated_at = now()
        WHERE id = ${id} AND status = 'proposed';
      COMMIT;`;
  } else if (proposalType === 'strategy_deactivation') {
    // target_type = Strategie. Deckt AP9s "Deaktivierung einer Strategie" ab -
    // "06" prueft trading.strategy_status vor jeder Kandidatenauswahl (Welle 3).
    sql = `BEGIN;
      UPDATE trading.strategy_status
        SET aktiv = FALSE, deactivated_at = now(), deactivated_reason = ${pgStr('Lernvorschlag #' + id)}, source_proposal_id = ${id}, updated_at = now()
        WHERE strategy = ${pgStr(targetType)} AND ${eligible};
      UPDATE trading.learning_rule_proposals
        SET status = 'activated', reviewed_at = now(), reviewed_by = ${pgStr(reviewer)}, activated_at = now()
        WHERE id = ${id} AND status = 'proposed';
      COMMIT;`;
  } else {
    // weight_adjustment (Original-Verhalten, unveraendert) - Weight-Key deterministisch
    // aus target_type+target_value(+time_horizon) gebaut, trading.scoring_weights hat
    // nur ein einzelnes Textfeld als Schluessel, kein zusammengesetzter Fremdschluessel.
    const timeHorizon = String(j.time_horizon || '').trim();
    const weightKey = [targetType, targetValue, timeHorizon].filter(Boolean).join(':');
    const proposedValue = pgNum(proposedValueRaw);
    sql = `BEGIN;
      UPDATE trading.scoring_weights SET active = FALSE
        WHERE weight_key = ${pgStr(weightKey)} AND active = TRUE AND ${eligible};
      INSERT INTO trading.scoring_weights
        (weight_key, weight_value, version, active, source_proposal_id, activated_at, activated_by, metadata_json)
      SELECT ${pgStr(weightKey)}, ${proposedValue}, COALESCE(MAX(version), 0) + 1, TRUE, ${id}, now(), ${pgStr(reviewer)}, '{}'::jsonb
        FROM trading.scoring_weights
        WHERE weight_key = ${pgStr(weightKey)} AND ${eligible};
      UPDATE trading.learning_rule_proposals
        SET status = 'activated', reviewed_at = now(), reviewed_by = ${pgStr(reviewer)}, activated_at = now()
        WHERE id = ${id} AND status = 'proposed';
      COMMIT;`;
  }
} else {
  sql = 'SELECT 1;';
}

return [{ json: { sql } }];

// FIX 2026-07-25: n8n-Plattform-Bug entdeckt - wenn eine Postgres-Abfrage 0 Zeilen liefert,
// wird der nachfolgende Node standardmaessig gar nicht ausgefuehrt, was die Webhook-Antwort
// crashen liess (leere Antwort, kein Fehler-Log, kein Execution-Eintrag - nur ueber Server-
// Logs als 'Task rejected by Runner: Offer expired' + interner n8n-TypeError sichtbar).
// Live reproduziert mit einer GARANTIERT leeren Abfrage auf einer bekannt funktionierenden
// Tabelle (trading.watchlist) - also kein Bug in dieser Tabelle/diesem Workflow, sondern ein
// generelles n8n-Verhalten. Fix: alwaysOutputData:true auf dem vorgelagerten Postgres-Node
// erzwingt ein (leeres) Platzhalter-Item, das hier herausgefiltert werden muss.
const rows = $input.all().map(i => i.json).filter(r => r && r.id !== undefined);

function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function fmtDate(v) {
  if (!v) return '';
  return new Date(v).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
}
function fmtNum(v) {
  return (v === null || v === undefined) ? '' : String(v);
}

const STATUS_LABEL = {
  proposed: 'wartet auf Pruefung',
  approved: 'freigegeben',
  activated: 'aktiviert',
  rejected: 'abgelehnt',
  expired: 'abgelaufen'
};
const STATUS_CLASS = {
  proposed: 'warn',
  approved: 'ok',
  activated: 'ok',
  rejected: 'danger',
  expired: 'muted'
};

const rowsHtml = rows.map(r => {
  const target = esc(r.target_type) + ': ' + esc(r.target_value) + (r.time_horizon ? ' @ ' + esc(r.time_horizon) : '');
  const change = fmtNum(r.current_value) + ' \u2192 <strong>' + fmtNum(r.proposed_value) + '</strong>';
  const metric = r.metric_name ? esc(r.metric_name) + ': ' + fmtNum(r.metric_value) : '';
  const badgeClass = STATUS_CLASS[r.status] || 'muted';
  const badgeLabel = STATUS_LABEL[r.status] || esc(r.status);
  const badge = '<span class="badge ' + badgeClass + '">' + esc(badgeLabel) + '</span>';

  let actionCell;
  if (r.status === 'proposed') {
    const approveId = 'fa-' + r.id;
    const rejectId = 'fr-' + r.id;
    const reviewerInputId = 'rev-' + r.id;
    actionCell = '<input id="' + reviewerInputId + '" form="' + approveId + '" name="reviewer" placeholder="Dein Name" required style="width:110px;display:inline-block;margin-right:4px;">' +
      '<button form="' + approveId + '" type="submit" onclick="return confirm(\'Vorschlag freigeben und sofort aktivieren?\')">Freigeben &amp; aktivieren</button>' +
      '<button class="danger" form="' + rejectId + '" type="submit" onclick="document.getElementById(\'' + rejectId + '\').reviewer.value = document.getElementById(\'' + reviewerInputId + '\').value || \'unbekannt\'; return confirm(\'Vorschlag ablehnen?\')">Ablehnen</button>' +
      '<form id="' + approveId + '" method="POST" action="/webhook/lernvorschlaege">' +
      '<input type="hidden" name="action" value="approve">' +
      '<input type="hidden" name="id" value="' + esc(r.id) + '">' +
      '<input type="hidden" name="proposal_type" value="' + esc(r.proposal_type) + '">' +
      '<input type="hidden" name="target_type" value="' + esc(r.target_type) + '">' +
      '<input type="hidden" name="target_value" value="' + esc(r.target_value) + '">' +
      '<input type="hidden" name="time_horizon" value="' + esc(r.time_horizon) + '">' +
      '<input type="hidden" name="proposed_value" value="' + esc(r.proposed_value) + '">' +
      '</form>' +
      '<form id="' + rejectId + '" method="POST" action="/webhook/lernvorschlaege">' +
      '<input type="hidden" name="action" value="reject">' +
      '<input type="hidden" name="id" value="' + esc(r.id) + '">' +
      '<input type="hidden" name="reviewer" value="">' +
      '</form>';
  } else {
    actionCell = esc(r.reviewed_by || '') + (r.activated_at ? ' \u00b7 ' + fmtDate(r.activated_at) : (r.reviewed_at ? ' \u00b7 ' + fmtDate(r.reviewed_at) : ''));
  }

  return '<tr>' +
    '<td>' + esc(r.id) + '</td>' +
    '<td>' + target + '</td>' +
    '<td>' + change + '</td>' +
    '<td>' + esc(r.sample_size) + '</td>' +
    '<td>' + esc(r.confidence_level) + '<br><span class="hint-inline">' + metric + '</span></td>' +
    '<td class="reason">' + esc(String(r.reason || '').slice(0, 220)) + '</td>' +
    '<td>' + badge + '<br><span class="hint-inline">' + fmtDate(r.created_at) + '</span></td>' +
    '<td>' + actionCell + '</td>' +
    '</tr>';
}).join('\n');

const now = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
const pendingCount = rows.filter(r => r.status === 'proposed').length;

const html = '<!DOCTYPE html>' +
'<html lang="de">' +
'<head>' +
'<meta charset="utf-8">' +
'<title>Lernvorschlaege freigeben</title>' +
'<style>' +
'  body { font-family: -apple-system, Segoe UI, Arial, sans-serif; background:#0f1115; color:#e6e6e6; margin:0; padding:32px; }' +
'  h1 { font-size:20px; margin-bottom:4px; }' +
'  .meta { color:#9aa0a6; font-size:13px; margin-bottom:8px; }' +
'  .hint { color:#9aa0a6; font-size:12px; margin-bottom:24px; }' +
'  .hint-inline { color:#9aa0a6; font-size:11px; }' +
'  table { border-collapse: collapse; width:100%; margin-bottom:16px; }' +
'  th, td { text-align:left; padding:8px 12px; border-bottom:1px solid #2a2d34; font-size:13px; vertical-align:top; }' +
'  th { color:#9aa0a6; font-weight:600; font-size:12px; text-transform:uppercase; letter-spacing:0.04em; }' +
'  td.reason { max-width:280px; }' +
'  input { background:#181b21; border:1px solid #2a2d34; color:#e6e6e6; border-radius:6px; padding:6px 8px; font-size:13px; box-sizing:border-box; }' +
'  input:focus { outline:1px solid #5b8def; }' +
'  button { background:#5b8def; border:none; color:#0f1115; font-weight:600; border-radius:6px; padding:6px 12px; font-size:12px; cursor:pointer; margin:2px 0; white-space:nowrap; display:block; }' +
'  button:hover { background:#7ba3f2; }' +
'  button.danger { background:#e0665a; color:#fff; }' +
'  button.danger:hover { background:#ef8177; }' +
'  .badge { display:inline-block; padding:2px 8px; border-radius:999px; font-size:11px; font-weight:600; }' +
'  .badge.ok { background:#1c3a2a; color:#6bcf8e; }' +
'  .badge.warn { background:#3a2c1c; color:#e0a854; }' +
'  .badge.danger { background:#3a1c1f; color:#e07a7a; }' +
'  .badge.muted { background:#22242a; color:#7a7d84; }' +
'</style>' +
'</head>' +
'<body>' +
'  <h1>Lernvorschlaege freigeben</h1>' +
'  <div class="meta">Stand: ' + now + ' &middot; ' + rows.length + ' Vorschlaege (' + pendingCount + ' wartend)</div>' +
'  <div class="hint">Vorschlaege aus 09 (Lernagent Newswirkung, Samstag 08:00). "Freigeben &amp; aktivieren" schreibt den neuen Gewichtswert sofort produktiv nach trading.scoring_weights (vorherige aktive Version wird deaktiviert, nicht geloescht) und markiert den Vorschlag als aktiviert. Name wird als reviewed_by/activated_by gespeichert.</div>' +
'  <table>' +
'    <thead><tr><th>ID</th><th>Ziel</th><th>Aktuell \u2192 Vorschlag</th><th>Fallzahl</th><th>Konfidenz</th><th>Begruendung</th><th>Status</th><th>Aktion</th></tr></thead>' +
'    <tbody>' + rowsHtml + '</tbody>' +
'  </table>' +
'</body>' +
'</html>';

return [{ json: { html } }];
